export function getMaterialIcon(name: string): string {
  name = name.toLowerCase();
  
  // Exact name matches first (like package.json)
  if (MATERIAL_FILE_MAP[name]) {
    return MATERIAL_FILE_MAP[name];
  }
  
  // Try matching vite.config.* etc.
  if (name.includes('vite.config')) return 'vite';
  if (name.includes('svelte.config')) return 'svelte';
  if (name.includes('tailwind.config')) return 'tailwindcss';
  if (name.includes('eslint.config')) return 'eslint';
  if (name.startsWith('.env')) return 'tune';
  
  // Fallback to extension
  const ext = name.split('.').pop() ?? '';
  return MATERIAL_FILE_MAP[ext] ?? 'document';
}

export function getMaterialFolderIcon(name: string): string {
  return MATERIAL_FOLDER_MAP[name.toLowerCase()] ?? 'base';
}
